// Calculate Amplenote-style Task Score (0-20 scale)
// Based on user's spiritual productivity philosophy

function calculateTaskScore(item) {
  let score = 0;

  // Note activity: +1 per day for frequently opened notes (max 7)
  if (item.last_opened) {
    const daysSinceOpened = Math.floor((Date.now() - new Date(item.last_opened).getTime()) / (1000 * 60 * 60 * 24));
    score += Math.min(Math.max(0, 7 - daysSinceOpened), 7);
  }

  // Urgency/Importance: +5 for urgent, +3 for important
  if (item.urgency === 'urgent') score += 5;
  if (item.importance === 'high') score += 3;

  // Deadlines: +10 if due today/overdue, +5 if due within 3 days
  if (item.due_date) {
    const dueDate = new Date(item.due_date);
    const daysUntilDue = Math.ceil((dueDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
    if (daysUntilDue <= 0) score += 10;
    else if (daysUntilDue <= 3) score += 5;
  }

  // Duration & blocking: +3 for quick wins (≤30 min), +2 for blockers
  if (item.estimated_duration && item.estimated_duration <= 30) score += 3;
  if (item.blocks_others) score += 2;

  // Cross-area impact: +2 per area affected
  if (item.affected_areas) {
    const areas = Array.isArray(item.affected_areas) ? item.affected_areas : 
                  (typeof item.affected_areas === 'string' ? item.affected_areas.split(',') : []);
    score += areas.length * 2;
  }

  return Math.min(score, 20); // Cap at 20
}

// Color coding based on score
function getTaskColor(score) {
  if (score >= 10) return 'red';
  if (score >= 5) return 'gold';
  return 'normal';
}

// Process each item
const results = [];
for (const item of $input.all()) {
  const score = calculateTaskScore(item);
  const color = getTaskColor(score);

  results.push({
    ...item,
    task_score: score,
    color_code: color,
    scored_at: new Date().toISOString(),
    score_breakdown: {
      activity: item.last_opened ? Math.min(Math.max(0, 7 - Math.floor((Date.now() - new Date(item.last_opened).getTime()) / (1000 * 60 * 60 * 24))), 7) : 0,
      urgency: item.urgency === 'urgent' ? 5 : 0,
      importance: item.importance === 'high' ? 3 : 0,
      deadline: item.due_date ? (Math.ceil((new Date(item.due_date).getTime() - Date.now()) / (1000 * 60 * 60 * 24)) <= 0 ? 10 : 
                Math.ceil((new Date(item.due_date).getTime() - Date.now()) / (1000 * 60 * 60 * 24)) <= 3 ? 5 : 0) : 0,
      quick_win: (item.estimated_duration && item.estimated_duration <= 30) ? 3 : 0,
      blocker: item.blocks_others ? 2 : 0,
      cross_impact: item.affected_areas ? 
        (Array.isArray(item.affected_areas) ? item.affected_areas.length : 
         (typeof item.affected_areas === 'string' ? item.affected_areas.split(',').length : 0)) * 2 : 0
    }
  });
}

return results;

